@dataclass(frozen=True)
class Settings:
    model_dir: str = ''
    device: str = 'cuda:0'
    dtype: str = 'bfloat16'
    max_length: int = 2048
    max_request_bytes: int = 65536
    max_questions: int = 16
    max_options: int = 32
    max_total_options: int = 128
    max_queue_size: int = 4
    api_key: str = field(default='', repr=False)

    @classmethod
    def from_env(cls, prefix: str='CLEF_') -> 'Settings':
        values: dict[str, Any] = {}
        from docker.model_services import selected_native
        adapter = 'nanojev' if prefix == 'NANOJEV_' else 'clef'
        record = selected_native(adapter)
        if record is not None:
            values.update(record.get('engine_options', {}))
            key_env = values.pop('api_key_env', {'clef': 'CLEF_API_KEY', 'nanojev': 'NANOJEV_API_KEY'}[adapter])
            values.pop('cpu_threads', None)
            values.update(model_dir='/models/' + record['model_dir'], device='cpu' if record['device'] == 'cpu' else 'cuda:0', api_key=config_getenv(key_env, '') if key_env else '')
        for name in list(values):
            if name.startswith('max_'):
                values[name] = int(values[name])
        settings = cls(**values)
        if any((getattr(settings, name) < 1 for name in cls.__dataclass_fields__ if name.startswith('max_'))):
            raise ValueError('CLEF limits must be positive')
        if settings.dtype not in {'bfloat16', 'float16', 'float32'}:
            raise ValueError('CLEF_DTYPE must be bfloat16, float16, or float32')
        if not (settings.device == 'cpu' or settings.device == 'cuda' or settings.device.startswith('cuda:')):
            raise ValueError('CLEF_DEVICE must select one CPU or CUDA device')
        return settings
